@OptIn(ExperimentalMaterial3Api::class) @Composable fun ExcelReaderScreen(onBack:()->Unit,vm:ExcelReaderViewModel=hiltViewModel()){
 val s by vm.state.collectAsStateWithLifecycle();var web by remember{mutableStateOf<WebView?>(null)};var search by remember{mutableStateOf(false)};var q by remember{mutableStateOf("")};var current by remember{mutableIntStateOf(0)};var total by remember{mutableIntStateOf(0)}
 LifecycleResumeEffect(Unit){vm.onResume();onPauseOrDispose{}};BackHandler(search){search=false;q="";web?.evaluateJavascript("searchSheet('')",null)};val access=rememberStorageAccessRequest(vm::onResume)
 LaunchedEffect(q,search,s.phase){delay(250);if(search&&s.phase==ExcelReaderPhase.Ready)web?.evaluateJavascript("searchSheet(${JSONObject.quote(q)})",null)}
 Scaffold(modifier=Modifier.fillMaxSize(),topBar={if(search)TopAppBar(title={TextField(q,{q=it},singleLine=true,placeholder={Text("Search worksheet")},trailingIcon={Text("$current of $total")})},navigationIcon={IconButton(onClick={search=false;q="";web?.evaluateJavascript("searchSheet('')",null)}){Icon(Icons.Default.Close,"Close search")}},actions={IconButton(enabled=total>0,onClick={web?.evaluateJavascript("nextMatch(-1)",null)}){Icon(Icons.Outlined.KeyboardArrowUp,"Previous")};IconButton(enabled=total>0,onClick={web?.evaluateJavascript("nextMatch(1)",null)}){Icon(Icons.Outlined.KeyboardArrowDown,"Next")}}) else TopAppBar(title={Text(s.fileName?:"Excel Reader",maxLines=1,overflow=TextOverflow.Ellipsis)},navigationIcon={IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")}},actions={if(s.phase==ExcelReaderPhase.Ready){IconButton(onClick={web?.evaluateJavascript("fitWidth()",null)}){Icon(Icons.Outlined.FitScreen,"Fit width")};IconButton(onClick={search=true}){Icon(Icons.Default.Search,"Search")}}})}){pad->
  val ready=s.ready;if(ready!=null&&s.phase in setOf(ExcelReaderPhase.PreparingViewer,ExcelReaderPhase.ParsingWorkbook,ExcelReaderPhase.Ready)){Column(Modifier.fillMaxSize().padding(pad)){ExcelWeb(ready,Modifier.fillMaxWidth().weight(1f),{web=it},{phase,c,t->current=c;total=t;vm.viewerPhase(phase)})}}else if(s.phase in setOf(ExcelReaderPhase.Resolving,ExcelReaderPhase.Validating))Box(Modifier.fillMaxSize().padding(pad),contentAlignment=Alignment.Center){CircularProgressIndicator()} else Message(s.phase,pad,onBack,if(s.phase==ExcelReaderPhase.PermissionDenied)access else vm::retry)
