@Composable private fun Message(p:ExcelReaderPhase,pad:PaddingValues,back:()->Unit,retry:()->Unit){val text=when(p){ExcelReaderPhase.PasswordProtected->"Password-protected spreadsheet" to "This spreadsheet is password protected and cannot be opened in the app yet.";ExcelReaderPhase.WrongOleFormat->"Not an Excel spreadsheet" to "This file uses another older Office format and cannot be opened as a spreadsheet.";ExcelReaderPhase.UnsupportedLegacyVersion,ExcelReaderPhase.UnsupportedFormat->"Spreadsheet format not supported" to "This spreadsheet uses an older format that is not supported yet.";ExcelReaderPhase.Corrupted,ExcelReaderPhase.FormatMismatch->"Spreadsheet could not be opened" to "The spreadsheet data is incomplete or invalid.";ExcelReaderPhase.PermissionDenied,ExcelReaderPhase.MissingFile->"Spreadsheet could not be accessed" to "Access to this spreadsheet is no longer available.";ExcelReaderPhase.RendererProcessCrashed->"Spreadsheet could not be opened" to "The spreadsheet renderer stopped.";ExcelReaderPhase.ParseTimeout->"Spreadsheet could not be opened" to "The workbook took too long to process.";ExcelReaderPhase.EmptyWorkbook->"Empty spreadsheet" to "This spreadsheet contains no worksheets.";ExcelReaderPhase.FileTooLarge,ExcelReaderPhase.SafetyLimit->"Spreadsheet could not be opened" to "This spreadsheet exceeds safe processing limits.";ExcelReaderPhase.WebViewUnavailable->"Spreadsheet could not be opened" to "Android System WebView is unavailable.";else->"Spreadsheet could not be opened" to "The spreadsheet could not be processed."};Column(Modifier.fillMaxSize().padding(pad).padding(32.dp),Arrangement.Center,Alignment.CenterHorizontally){Icon(Icons.Outlined.TableChart,null,Modifier.size(52.dp));Text(text.first,style=MaterialTheme.typography.titleMedium);Text(text.second);Row{TextButton(onClick=back){Text("Back")};if(p !in setOf(ExcelReaderPhase.PasswordProtected,ExcelReaderPhase.UnsupportedLegacyVersion,ExcelReaderPhase.UnsupportedFormat,ExcelReaderPhase.WrongOleFormat,ExcelReaderPhase.EmptyWorkbook,ExcelReaderPhase.FileTooLarge,ExcelReaderPhase.SafetyLimit))Button(onClick=retry){Text("Try again")}}}}
